    params: "u16 i, u8 r, u8 g, u8 b",
    lineCount: 12,
    bodyC: "int curRed, curGreen, curBlue;\n    u16 color = gPlttBufferUnfaded[i];\n\n    curRed   = (color & RGB_RED);\n    curGreen = (color & RGB_GREEN) >>  5;\n    curBlue  = (color & RGB_BLUE)  >> 10;\n\n    curRed   -= ((curRed   * r) >> 4);\n    curGreen -= ((curGreen * g) >> 4);\n    curBlue  -= ((curBlue  * b) >> 4);\n\n    color  = curRed;\n    color |= (curGreen <<  5);\n    color |= (curBlue  << 10);\n\n    gPlttBufferFaded[i] = color;",
